import{_ as i,l as o,o as e,c as n,v as r,p as l,x as t,d,i as h,S as c}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"分片直觉","description":"","frontmatter":{"title":"分片直觉","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/sharding.md","filePath":"cs/sharding.md","lastUpdated":1789023840000}'),p={name:"cs/sharding.md"};function E(_,a,m,A,f,C){const s=o("Mermaid");return e(),n("div",null,[a[1]||(a[1]=r('<h1 id="分片直觉" tabindex="-1">分片直觉 <a class="header-anchor" href="#分片直觉" aria-label="Permalink to &quot;分片直觉&quot;">​</a></h1><div class="epigraph"><p>按键把关系水平切开，每片一台机器；片内仍是事务与 WAL，片间默认没有同一套 ACID。</p><footer>—— 据 Gray 对规模；Ramakrishnan 对水平划分；对照 2PC 的代价</footer></div><p><a href="/cs/replication-log">上一课</a>用日志做同一历史的副本。本课不重做同步复制。缺口是容量与写吞吐：复制不减小单片数据量。分片（sharding）按分片键划分元组。跨片查询是连接与 2PC 的边界。数据库课在此结束，下一课 CIA。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>复制留下「多份同一数据」。写仍然打在主片的那一份上，磁盘与 CPU 仍线性涨。水平切分：<code>hash(k) mod N</code> 或按范围。请求路由用键；没有键的查询要打所有片或维护二级索引。缺口是<strong>把关系当成可切开的集合</strong>，以及跨片事务不再免费。</p><p><span class="marginnote">垂直切分是按列分文件，对象不同。本课水平。再均衡（reshard）要搬元组与日志点，是运维缺口，不展开成手册。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>选分片键使常见事务落在单片（如用户 id）。片内 <a href="/cs/strict-2pl">严格 2PL</a> 与 ARIES 照旧。跨片原子用 2PC 或改成最终一致。外键跨片难以强制，<a href="/cs/fk-actions">参照动作</a> 常退回应用。查询计划多一层：先剪枝片，再在片上优化。</p>',8)),(e(),l(c,null,{default:t(()=>[h(s,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20REL%5B%22%E5%85%B3%E7%B3%BB%22%5D%20--%3E%20KEY%5B%22%E5%88%86%E7%89%87%E9%94%AE%22%5D%0A%20%20KEY%20--%3E%20S1%5B%22%E7%89%87%201%22%5D%0A%20%20KEY%20--%3E%20S2%5B%22%E7%89%87%202%22%5D%0A%20%20TX%5B%22%E5%8D%95%E7%89%87%E4%BA%8B%E5%8A%A1%22%5D%20--%3E%20LOCAL%5B%22%E6%9C%AC%E5%9C%B0%20WAL%22%5D%0A%20%20CROSS%5B%22%E8%B7%A8%E7%89%87%22%5D%20--%3E%20TPC%5B%222PC%20%E6%88%96%E6%94%BE%E5%BC%83%E5%8E%9F%E5%AD%90%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>分片把<a href="/cs/page-slot">页与槽</a> 的局部性限制在一片内，网络成为新的「寻道」。副本可以每片一套，与分片正交。安全课将开始：切分不提供保密，只改变攻击面形状。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 NewSQL 全球时间戳当主干必选。提交可以正确，报文仍可被窃听——下一课 CIA 三元组。</p><p>后课默认：库可以水平切开。安全课换敌手模型，不再补一种分片算法。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>水平分片按键切开；片内事务，片间需 2PC 或弱化。</li><li>复制与分片正交。</li><li>计算机栏下一课进入 CIA。</li><li>出处：Gray；Ramakrishnan and Gehrke；对照 Bernstein 对 2PC。</li></ul>',7))])}const P=i(p,[["render",E]]);export{B as __pageData,P as default};
